    return segment.split(":", 1)[0]


def is_prefix_match(namespace: list[str], prefix: list[str]) -> bool:
    """Return True if ``namespace`` starts with all segments in ``prefix``.

    Each namespace segment is normalized (colon-suffix stripped) before
    comparison. A prefix segment that itself contains a colon is treated as
    an exact literal and compared against the raw namespace segment. An
    empty prefix matches any namespace; a prefix longer than the namespace
    never matches.
